    n = len(S)
    MOD = 998244353

    # dp[i][j] = number of ways to process prefix of length i with balance j
    # balance = number of '(' minus number of ')'
    # We only need balances from 0 to n (cannot exceed n)
    dp = [0] * (n + 2)
    dp[0] = 1

    for i, ch in enumerate(S):
