        for j in range(n + 1):
            if dp[j] == 0:
                continue
            if ch == '(':
                if j + 1 <= n:
                    new_dp[j + 1] = (new_dp[j + 1] + dp[j]) % MOD
            elif ch == ')':
                if j - 1 >= 0:
                    new_dp[j - 1] = (new_dp[j - 1] + dp[j]) % MOD
            else:  # ch == '?'
                # Try '('
